const j = $input.first().json;
const route = j.mode ? String(j.mode) : ((j.submittedAt || j.formMode) ? 'form' : 'community');
const pl = [].concat(j.platforms || ['Facebook', 'Instagram']).map(p => String(p).toLowerCase()).filter(p => ['facebook', 'instagram', 'tiktok'].includes(p));
const mt = String(j.media_type || 'none').toLowerCase();
const media_type = mt.startsWith('image') ? 'image' : mt.startsWith('video') ? 'video' : 'none';
let brief = String(j.brief || j.post_text || '').trim();
if (!brief && Array.isArray(j.social_posts)) brief = JSON.stringify(j.social_posts.filter(p => /facebook|instagram|tiktok/i.test(p.platform || '')).slice(0, 6));
return [{ json: {
  route,
  brief,
  ai_captions: j.caption_mode ? /AI/i.test(j.caption_mode) : true,
  platforms: pl,
  platform_labels: pl.map(p => p === 'tiktok' ? 'TikTok' : p.charAt(0).toUpperCase() + p.slice(1)).join(','),
  media_type,
  media_url: String(j.media_url || '').trim(),
  link: String(j.link || '').trim(),
  when: /schedule/i.test(String(j.publish_when || '')) ? 'schedule' : 'now',
  schedule_at: String(j.schedule_at || '').trim(),
  language: j.language || 'Arabic (Egyptian)',
  captions: j.captions || null,
  campaign_context: String(j.campaign_context || '')
} }];

