function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  return typeof j.text === 'string' ? j.text : JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return {};
}
const n = $('Normalize Social Request').first().json;
const r = parseJson(textOf($input.first().json));
const cap = k => (r[k] && r[k].caption) || '';
const has = p => n.platforms.includes(p);
const facebook_caption = has('facebook') ? cap('facebook') || n.brief : '';
const instagram_caption = has('instagram') ? cap('instagram') || n.brief : '';
const tiktok_caption = has('tiktok') ? cap('tiktok') || n.brief.slice(0, 150) : '';
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const warn = [];
if ((has('instagram') || has('tiktok')) && n.media_type === 'none') warn.push('Instagram and TikTok need an image or video - they will be skipped.');
if (n.media_type !== 'none' && !/^https?:\/\//i.test(n.media_url)) warn.push('The media URL is missing or not public - media posts will fail.');
if (has('tiktok') && n.media_type === 'image') warn.push('TikTok photo posts need a URL on a domain verified in your TikTok developer app.');
const preview = '<p><b>Media:</b> ' + esc(n.media_type) + (n.media_url ? ' - ' + esc(n.media_url) : '') + '<br><b>When:</b> ' + (n.when === 'schedule' ? esc(n.schedule_at) : 'now') + (r.best_time ? '<br><b>AI suggested time:</b> ' + esc(r.best_time) : '') + '</p>' + (warn.length ? '<p style="color:#c4320a"><b>' + warn.map(esc).join('<br>') + '</b></p>' : '') + (n.media_type === 'image' && n.media_url ? '<p><img src="' + esc(n.media_url) + '" style="max-width:100%;max-height:260px;border-radius:8px"></p>' : '') + '<p>Edit the captions below if needed, then approve.</p>';
return [{ json: { ...n, facebook_caption, instagram_caption, tiktok_caption, instagram_first_comment: (r.instagram && r.instagram.first_comment) || '', best_time: r.best_time || '', notes: r.notes || '', warnings: warn, preview_html: preview } }];

const s = $('Social Settings').first().json;
const n = $('Normalize Social Request').first().json;
let approved = true;
let captions = n.captions || {};
let platforms = n.platforms;
if (n.route === 'form') {
  const f = $('Review & Approve').first().json;
  approved = /approve/i.test(String(f.decision || ''));
  captions = { facebook: f.facebook_caption, instagram: f.instagram_caption, tiktok: f.tiktok_caption };
  platforms = [].concat(f.final_platforms || []).map(p => String(p).toLowerCase());
} else if (!n.captions) {
  captions = { facebook: n.brief, instagram: n.brief, tiktok: n.brief.slice(0, 150) };
}
let publishAt = $now;
if (n.when === 'schedule' && n.schedule_at) {
  const dt = DateTime.fromFormat(n.schedule_at, 'yyyy-MM-dd HH:mm', { zone: s.timezone || 'UTC' });
  if (dt.isValid && dt > $now) publishAt = dt;
}
const mt = n.media_type, url = n.media_url;
const hasMedia = mt !== 'none' && /^https?:\/\//i.test(url);
const fbText = String(captions.facebook || '');
let fb_edge = 'feed', fb_host = 'graph.facebook.com', fb_body = { message: fbText };
if (n.link && mt === 'none') fb_body.link = n.link;
if (hasMedia && mt === 'image') { fb_edge = 'photos'; fb_body = { url, message: fbText }; }
if (hasMedia && mt === 'video') { fb_edge = 'videos'; fb_host = 'graph-video.facebook.com'; fb_body = { file_url: url, description: fbText }; }
const igText = String(captions.instagram || '');
const ig_body = mt === 'video' ? { media_type: 'REELS', video_url: url, caption: igText } : { image_url: url, caption: igText };
const ttText = String(captions.tiktok || '');
const privacy = s.tiktok_privacy || 'SELF_ONLY';
const tiktok_url = mt === 'video' ? 'https://open.tiktokapis.com/v2/post/publish/video/init/' : 'https://open.tiktokapis.com/v2/post/publish/content/init/';
const tiktok_body = mt === 'video'
  ? { post_info: { title: ttText.slice(0, 2200), privacy_level: privacy, disable_comment: false, disable_duet: false, disable_stitch: false }, source_info: { source: 'PULL_FROM_URL', video_url: url } }
  : { post_info: { title: ttText.slice(0, 90), description: ttText.slice(0, 4000), privacy_level: privacy, disable_comment: false }, source_info: { source: 'PULL_FROM_URL', photo_cover_index: 0, photo_images: [url] }, post_mode: 'DIRECT_POST', media_type: 'PHOTO' };
const skipped = [];
const do_fb = approved && platforms.includes('facebook') && !!fbText && !!s.facebook_page_id;
if (approved && platforms.includes('facebook') && !s.facebook_page_id) skipped.push('Facebook: set facebook_page_id in Social Settings');
const do_ig = approved && platforms.includes('instagram') && hasMedia;
if (approved && platforms.includes('instagram') && !hasMedia) skipped.push('Instagram: needs a public image or video URL');
const do_tt = approved && platforms.includes('tiktok') && hasMedia;
if (approved && platforms.includes('tiktok') && !hasMedia) skipped.push('TikTok: needs a public image or video URL');
return [{ json: { approved, route: n.route, platforms, media_type: mt, media_url: url, publish_at: publishAt.toISO(), scheduled: publishAt > $now.plus({ minutes: 1 }), do_fb, do_ig, do_tt, fb_edge, fb_host, fb_body, ig_body, tiktok_url, tiktok_body, captions, skipped } }];

const job = $('Prepare Publish Jobs').first().json;
function first(name) { try { return $(name).first().json; } catch (e) { return null; } }
function errOf(r) { if (!r) return null; if (r.error && typeof r.error === 'object' && r.error.code && r.error.code !== 'ok') return r.error.message || JSON.stringify(r.error); if (r.error && typeof r.error === 'string') return r.error; if (r.error && r.error.message && !r.error.code) return r.error.message; return null; }
const results = [];
if (!job.approved) results.push({ platform: 'All', status: 'cancelled', detail: 'You cancelled - nothing was published.' });
const tok = first('Get Page Token');
if (job.do_fb) { const r = first('Publish to Facebook'); const e = errOf(r) || errOf(tok); results.push({ platform: 'Facebook', status: e ? 'failed' : 'published', detail: e || ('Post ID ' + (r.post_id || r.id || '')) }); }
if (job.do_ig) { const c = first('Create Instagram Container'); const r = first('Publish Instagram Container'); const e = errOf(c) || errOf(r); results.push({ platform: 'Instagram', status: e ? 'failed' : 'published', detail: e || ('Media ID ' + ((r && r.id) || '')) }); }
if (job.do_tt) { const r = first('Publish to TikTok'); const e = errOf(r); results.push({ platform: 'TikTok', status: e ? 'failed' : 'sent to TikTok', detail: e || ('Publish ID ' + ((r && r.data && r.data.publish_id) || '') + ' - TikTok processes it in a few minutes. Privacy: ' + (($('Social Settings').first().json.tiktok_privacy) || 'SELF_ONLY')) }); }
(job.skipped || []).forEach(s => results.push({ platform: s.split(':')[0], status: 'skipped', detail: s }));
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const color = { published: '#12805c', 'sent to TikTok': '#12805c', failed: '#c4320a', skipped: '#b54708', cancelled: '#667085' };
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:15px/1.6 system-ui,Segoe UI,Tahoma,sans-serif;background:#f6f7fb;color:#1d2433;margin:0}.w{max-width:720px;margin:24px auto;padding:0 16px}.c{background:#fff;border:1px solid #e4e7ec;border-radius:12px;padding:16px;margin:10px 0}b.s{color:#fff;border-radius:99px;padding:1px 10px;font-size:12px}</style></head><body><div class="w"><h2>Publishing result</h2><p>' + esc(job.publish_at) + '</p>' + results.map(r => '<div class="c"><b>' + esc(r.platform) + '</b> <b class="s" style="background:' + (color[r.status] || '#667085') + '">' + esc(r.status) + '</b><p>' + esc(r.detail) + '</p></div>').join('') + '</div></body></html>';
return [{ json: { route: job.route, results, html } }];

const s = $('Social Settings').first().json;
function first(n) { try { return $(n).first().json || {}; } catch (e) { return {}; } }
function all(n) { try { return $(n).all(); } catch (e) { return []; } }
const since = $now.minus({ hours: 72 });
const recent = t => { const d = DateTime.fromISO(String(t || '').replace(/\+0000$/, 'Z')); return !d.isValid || d >= since; };
const out = [];
(first('Get Facebook Comments').data || []).forEach(post => {
  ((post.comments && post.comments.data) || []).forEach(c => {
    if (!c.message || (c.from && String(c.from.id) === String(s.facebook_page_id)) || c.comment_count > 0 || !recent(c.created_time)) return;
    out.push({ platform: 'facebook', comment_id: c.id, post_id: post.id, post_text: String(post.message || '').slice(0, 300), author: (c.from && c.from.name) || '', text: c.message, created: c.created_time, link: post.permalink_url || '' });
  });
});
(first('Get Instagram Comments').data || []).forEach(m => {
  ((m.comments && m.comments.data) || []).forEach(c => {
    if (!c.text || (c.replies && c.replies.data && c.replies.data.length) || !recent(c.timestamp)) return;
    out.push({ platform: 'instagram', comment_id: c.id, post_id: m.id, post_text: String(m.caption || '').slice(0, 300), author: c.username || '', text: c.text, created: c.timestamp, link: m.permalink || '' });
  });
});
const vids = all('Pick Recent TikTok Videos');
all('Get TikTok Comments').forEach((it, i) => {
  const vid = (vids[i] && vids[i].json) || {};
  (((it.json || {}).data || {}).comments || []).forEach(c => {
    if (!c.text || c.owner || Number(c.reply_count) > 0) return;
    out.push({ platform: 'tiktok', comment_id: c.comment_id, post_id: vid.video_id || c.video_id || '', post_text: String(vid.caption || '').slice(0, 300), author: c.username || c.display_name || '', text: c.text, created: c.create_time ? DateTime.fromSeconds(Number(c.create_time)).toISO() : '', link: '' });
  });
});
return out.slice(0, 40).map(json => ({ json }));

values.content:
=BRAND: {{ $("Social Settings").first().json.brand_name || "our brand" }}
BRAND VOICE: {{ $("Social Settings").first().json.brand_voice }}

New comments from Facebook, Instagram and TikTok (JSON):
{{ JSON.stringify($input.all().map(i => ({ comment_id: i.json.comment_id, platform: i.json.platform, post: i.json.post_text, author: i.json.author, comment: i.json.text }))) }}

For EVERY comment: classify sentiment and intent, set priority, and write a short, warm, human reply in the SAME language and dialect as the comment (max 2 sentences, no hashtags). Questions about price, dates or availability: answer only if the post text contains the answer, otherwise invite them to DM / message us. Set needs_human=true (and still draft a reply) for complaints, refunds, legal, medical, angry or sensitive comments, or anything you are unsure about. Spam or offensive: intent "spam", reply "". Also write a short summary of the overall audience mood and list urgent alerts.

JSON shape:
{"summary":"","alerts":[""],"replies":[{"comment_id":"","sentiment":"positive|neutral|negative","intent":"question|lead|praise|complaint|spam|other","priority":"high|medium|low","reply":"","needs_human":false,"reason":""}]}
Return ONLY one valid JSON object.

