function textOf(j) {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  const parts = (j.content && j.content.parts) || (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts);
  if (Array.isArray(parts)) return parts.map(p => p.text || '').join('');
  return typeof j.text === 'string' ? j.text : JSON.stringify(j);
}
function parseJson(t) {
  const s = String(t || '').trim().replace(/^\s*\x60\x60\x60(?:json)?/i, '').replace(/\x60\x60\x60\s*$/, '');
  const a = s.indexOf('{'); const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return {};
}
const r = parseJson(textOf($input.first().json));
const byId = {}; (r.replies || []).forEach(x => { byId[String(x.comment_id)] = x; });
const merged = $('Skip Already Handled').all().map(i => Object.assign({}, i.json, byId[String(i.json.comment_id)] || { reply: '', needs_human: true, sentiment: 'neutral', intent: 'other', priority: 'medium', reason: 'no AI reply' }));
function esc(v) { return String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const autoCount = merged.filter(m => m.reply && !m.needs_human && m.intent !== 'spam').length;
const col = { positive: '#12805c', neutral: '#667085', negative: '#c4320a' };
let html = '<h2>' + merged.length + ' new comments - ' + autoCount + ' replies ready</h2><p>' + esc(r.summary) + '</p>';
if ((r.alerts || []).length) html += '<p style="color:#c4320a"><b>Alerts:</b><br>' + r.alerts.map(esc).join('<br>') + '</p>';
html += '<table cellpadding="8" style="border-collapse:collapse;width:100%;font-family:Segoe UI,Tahoma,sans-serif;font-size:14px">' + merged.map(m => '<tr style="border-bottom:1px solid #e4e7ec"><td style="vertical-align:top;width:90px"><b>' + esc(m.platform) + '</b><br><span style="color:' + (col[m.sentiment] || '#667085') + '">' + esc(m.sentiment) + '</span><br><small>' + esc(m.intent) + ' · ' + esc(m.priority) + '</small></td><td style="vertical-align:top"><b>' + esc(m.author) + ':</b> ' + esc(m.text) + '<br><small style="color:#667085">on: ' + esc(String(m.post_text).slice(0, 80)) + '</small><br>' + (m.needs_human ? '<span style="color:#b54708"><b>Needs you - NOT auto-replied:</b> ' + esc(m.reason) + '</span><br><i>Suggested: ' + esc(m.reply) + '</i>' : (m.reply ? '<span style="color:#12805c"><b>Reply:</b></span> ' + esc(m.reply) : '<i>no reply (spam)</i>')) + '</td></tr>').join('') + '</table><p>Approve to post the green replies. Comments marked "Needs you" are never posted automatically.</p>';
return [{ json: { count: merged.length, auto_count: autoCount, summary: r.summary || '', merged, html } }];

const approved = !!((($input.first().json || {}).data || {}).approved);
const merged = $('Build Approval Email').first().json.merged || [];
return merged.map(m => {
  let action = 'skip', status = approved ? 'no_reply' : 'declined';
  if (m.intent === 'spam') status = 'spam';
  else if (m.needs_human) status = 'escalated';
  else if (approved && m.reply) { action = 'reply'; status = 'replied'; }
  return { json: Object.assign({}, m, { action, status }) };
});

const merged = $input.first().json.merged || [];
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
const phoneRe = /(\+?\d[\d\s-]{8,}\d)/;
return merged
  .filter(m => m.intent === 'lead' || (m.intent === 'question' && m.priority === 'high'))
  .map(m => {
    const text = String(m.text || '');
    const email = (text.match(emailRe) || [''])[0];
    const phone = ((text.match(phoneRe) || [''])[0] || '').replace(/[\s-]/g, '');
    return { json: {
      name: m.author || 'there',
      email,
      phone,
      company: '',
      source: 'social_' + m.platform,
      campaign: String(m.post_text || '').slice(0, 80),
      message: text,
      engagement: 'Commented on our ' + m.platform + ' post ("' + String(m.post_text || '').slice(0, 120) + '"). AI intent: ' + m.intent + ', priority: ' + m.priority + ', sentiment: ' + m.sentiment + '. Link: ' + (m.link || 'n/a'),
      preferredChannel: phone ? 'whatsapp' : 'email'
    } };
  });
